@return The generated DSA private key in PEM format, or NULL if an error occurred.
*/
char* create_dsa_key() {
    char param_filename[] = "/tmp/tempXXXXXX";
    // mkstemp creates a unique temporary file and returns a file descriptor.
    // The file is created with permissions that are secure by default.
    int fd = mkstemp(param_filename);
    if (fd == -1) {
        // Error creating temporary file
        return NULL;
    }
    // Close the file descriptor as openssl will open the file by its name.
    close(fd);

    // Generate DSA parameters. The output is written to the temporary file.
    // We use a fixed key length of 2048 bits as per common practice.
    // The command is constructed to be safe by using the generated filename.
    char dsaparam_command[256];
    snprintf(dsaparam_command, sizeof(dsaparam_command), "openssl dsaparam -out %s 2048", param_filename);

    // Execute the command to generate DSA parameters.
    // We don't need the output of this command, only the side effect of creating the file.
    char* dsaparam_output = execute_command(dsaparam_command);
    if (dsaparam_output == NULL) {
        // Error during parameter generation, clean up the temporary file.
        unlink(param_filename);
        return NULL;
    }
    // Free the output from execute_command as it's not needed.
    free(dsaparam_output);

    // Generate DSA private key using the generated parameters.
    // The output of this command will be the PEM-formatted private key.
    char gendsa_command[256];
    snprintf(gendsa_command, sizeof(gendsa_command), "openssl gendsa -paramfile %s", param_filename);

    // Execute the command to generate the DSA private key.
    char* private_key_pem = execute_command(gendsa_command);

    // Clean up the temporary parameter file regardless of whether key generation succeeded.
    unlink(param_filename);

    // Return the generated private key in PEM format.
    // If execute_command failed, private_key_pem will be NULL, which is the desired behavior.
    return private_key_pem;
}
